-- Compact historic import (set-based)
begin;

values ('settlements', 'Settlements', 'repeat', 85, true)
on conflict (key) do nothing;

create temporary table tmp_historic_import (
  row_no int generated always as identity primary key,
  payment_date date not null,
  title text not null,
  amount numeric(12,2) not null,
  currency_code text not null,
  category_key text not null,
  source_type finance_app.payment_source_type not null,
  payer_name text not null,
  counterparty_name text not null,
  split_payer numeric(12,2) not null,
  split_counterparty numeric(12,2) not null
) on commit drop;


-- Preconditions
do $$ begin
  if (select count(*) from finance_app.households) = 0 then
    raise exception 'No household found. Run setup household SQL first.';
  end if;
  if (select count(*) from finance_app.household_members where display_name in ('Ben Selby','Louise Billingham')) < 2 then
    raise exception 'Ben/Louise household members not found. Run setup household SQL first.';
  end if;
end $$;

create temporary table tmp_inserted_payments (
  row_no int primary key,
  payment_id uuid not null,
  payer_user_id uuid not null,
  counterparty_user_id uuid not null,
  amount numeric(12,2) not null,
  split_payer numeric(12,2) not null,
  split_counterparty numeric(12,2) not null
) on commit drop;

with ctx as (
  select h.id as household_id from finance_app.households h order by h.created_at asc limit 1
), resolved as (
  select
    t.row_no, t.payment_date, t.title, t.amount, t.currency_code, t.category_key, t.source_type, t.split_payer, t.split_counterparty,
    p.user_id as payer_user_id, c.user_id as counterparty_user_id
  from tmp_historic_import t
  join finance_app.household_members p on p.display_name = t.payer_name and p.is_active = true
  join finance_app.household_members c on c.display_name = t.counterparty_name and c.is_active = true
), ins as (
  select ctx.household_id, r.title, r.amount, r.currency_code, 1, r.payment_date, r.amount, r.payment_date, r.category_key, null, r.source_type, r.payer_user_id
  from resolved r cross join ctx
  returning id, title, amount, payment_date, created_by
)
select r.row_no, i.id, r.payer_user_id, r.counterparty_user_id, r.amount, r.split_payer, r.split_counterparty
from ins i
join resolved r on r.title = i.title and r.amount = i.amount and r.payment_date = i.payment_date and r.payer_user_id = i.created_by;

select payment_id, payer_user_id, amount from tmp_inserted_payments;

select payment_id, payer_user_id, split_payer from tmp_inserted_payments where split_payer > 0
union all
select payment_id, counterparty_user_id, split_counterparty from tmp_inserted_payments where split_counterparty > 0;

commit;